---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Error and recovery: A failed step with retry, skip or hand over to a person.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change error-recovery.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './error-recovery.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', 'bare', className]} data-c="error-recovery" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="erx panel">
  <div class="erx-h"><span class="erx-t">Sync the pipeline to Sheets</span><span class="erx-s muted">Stopped at step 2</span></div>
  <div class="erx-list"></div>
  <div class="fold erx-box"><div><div class="erx-in">
    <div class="erx-q">How should the agent continue?</div>
    <div class="erx-opts" role="radiogroup">
      <button class="erx-o on" data-o="retry" role="radio" aria-checked="true"><i></i><span>Ask for edit access, then retry</span></button>
      <button class="erx-o" data-o="skip" role="radio" aria-checked="false"><i></i><span>Skip it and post the summary</span></button>
      <button class="erx-o" data-o="hand" role="radio" aria-checked="false"><i></i><span>Hand it over to Maya</span></button>
    </div>
    <button class="pill primary sm erx-go">Continue</button>
  </div></div></div>
</div>
  </Fragment></div>
</div>
<script>
  import './error-recovery.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Error and recovery ---------- */
.erx{padding:var(--dm-s-2)}
.erx-h{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-3);padding:var(--dm-s-2) 10px 6px}
.erx-t{font-weight:500}
.erx-s{font-size:12.5px;white-space:nowrap}
.erx-list{padding:2px 10px 6px}
.erx-row{position:relative;display:flex;gap:10px;padding:6px 0 6px var(--dm-s-6);font-size:13.5px;color:var(--dm-fg)}
.erx-row .g{position:absolute;left:0;top:7px;width:16px;height:16px;display:grid;place-items:center}
.erx-row:not(:last-child)::before{content:"";position:absolute;left:7.5px;top:25px;bottom:-6px;width:1px;background:var(--dm-rail)}
.erx-row .d{display:block;font-size:12.5px;color:var(--dm-muted);transition:color .3s}
.erx-row.wait{color:var(--dm-muted)}
.erx-row.fail .d{color:var(--dm-bad)}
.erx-row.skip .tx{text-decoration:line-through;color:var(--dm-muted)}
.erx-in{margin:var(--dm-s-1) 0 0;padding:var(--dm-s-2) 10px 2px}
.erx-q{font-size:13px;font-weight:500;margin-bottom:var(--dm-s-2)}
.erx-opts{display:flex;flex-direction:column;gap:2px;margin:0 -10px var(--dm-s-3)}
.erx-o{display:flex;align-items:center;gap:10px;padding:var(--dm-s-2) 10px;border-radius:calc(10px * var(--dm-rk));font-size:13px;text-align:left;color:var(--dm-fg2);transition:background .25s,color .25s}
@media (hover:hover) and (pointer:fine){.erx-o:hover{background:var(--dm-row);color:var(--dm-fg)}}
.erx-o.on{background:var(--dm-sel);color:var(--dm-fg)}
.erx-o i{width:15px;height:15px;border-radius:50%;box-shadow:inset 0 0 0 1.5px color-mix(in srgb,var(--dm-muted) 80%,var(--dm-surface));flex:none;transition:box-shadow .35s var(--dm-ease)}
.erx-o.on i{box-shadow:inset 0 0 0 4.5px var(--dm-accent-mark,var(--dm-accent))}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, enter, swap } from '../core/core.js';
DM.def('error-recovery', (r, c) => {
  const list = $('.erx-list', r), box = $('.erx-box', r), go = $('.erx-go', r), sum = $('.erx-s', r), opts = $$('.erx-o', r);
  const steps = [['Pull 1,240 deals from the CRM'],['Write to the Pipeline 2026 sheet'],['Post the summary in #sales']];
  list.innerHTML = steps.map(s => `<div class="erx-row"><span class="g"></span><span class="tx">${s[0]}<span class="d"></span></span></div>`).join('');
  const rows = $$('.erx-row', r);
  const G = { done:`<span style="color:var(--dm-ok)">${I('check','xs')}</span>`, fail:`<span style="color:var(--dm-bad)">${I('alert','xs')}</span>`, run:'<span class="spin"></span>', wait:'<span class="dot" style="color:var(--dm-faint)"></span>', skip:`<span class="muted">${I('chev-r','xs')}</span>`, hand:`<span style="color:var(--dm-pl)">${I('user','xs')}</span>` };
  const set = (i, st, note) => { const rw = rows[i]; rw.className = 'erx-row ' + st; const g = $('.g', rw); g.innerHTML = G[st]; enter(g); swap($('.d', rw), note || ''); };
  set(0, 'done', 'Done in 8s'); set(1, 'fail', 'Error 403: the agent lost edit access to this sheet'); set(2, 'wait');
  let pick = 'retry';
  opts.forEach(o => o.onclick = () => { pick = o.dataset.o; opts.forEach(x => { x.classList.toggle('on', x === o); x.setAttribute('aria-checked', x === o); }); });
  go.onclick = () => c.run(async () => {
    box.classList.add('shut');
    if (pick === 'retry'){
      set(1, 'run', 'Asking for edit access'); swap(sum, 'Recovering'); await c.wait(1200);
      set(1, 'run', 'Access granted, retrying'); await c.wait(1000);
      set(1, 'done', 'Wrote 1,240 rows'); set(2, 'run'); await c.wait(1000);
      set(2, 'done', 'Posted to 14 people'); swap(sum, 'Recovered');
    } else if (pick === 'skip'){
      set(1, 'skip', 'Skipped, nothing was written'); set(2, 'run'); await c.wait(1000);
      set(2, 'done', 'Posted, with a note about the sheet'); swap(sum, '2 of 3 done');
    } else {
      set(1, 'hand', 'Maya has the error, the logs and the last good state'); swap(sum, 'Waiting on Maya');
    }
  });
});
